    // --- Field help: the longer explanation behind a "?" (ADMIN-UI.md) -------
    'help.settings.general' => "This is where you fill in who your website is: its name, its logo and how people can reach you.\n\nOnly the <strong>website name</strong> is required. Fill in everything else if you want to use it; whatever stays empty appears nowhere.",
    'help.settings.site_name' => "The name of your website, as visitors know you. It does not have to be an official business name: a personal website simply has a name.\n\nIt appears in the browser tab, in search results such as Google's (after a page's title), at the bottom of the website and as the sender of the emails the website sends. That is why it is the only field on this page you must fill in.",
    'help.settings.kvk_number' => "The number your business is registered under at the Dutch Chamber of Commerce (KVK). It has eight digits.\n\nIf your business is registered, this number usually belongs on your website. It then appears at the bottom of the website; you can switch that off under <strong>Footer</strong>. If you are not registered, for a personal website for example, leave it empty.",
    'help.settings.email' => "Your website's general email address. You do not have to fill it in, but without it the website cannot send you any messages.\n\nMessages visitors send through a form arrive here when that form has no address of its own. The emails the website sends also come from this address, unless your hosting provider has set up a different sender address.\n\nVisitors see the address at the bottom of the website (you can switch that off under <strong>Footer</strong>) and in a contact block, if you put one on a page. <strong>Use an address you actually read.</strong>",
    'help.settings.phone' => "A phone number people can reach you on.\n\nIt appears at the bottom of the website if you switch that on under <strong>Footer</strong>. Leave it empty if you do not want to be called.",
    'help.settings.city' => "The town or region visitors see with your contact details, for example next to a contact form. If you leave it empty, that line does not appear.\n\nThis is not a postal address. You fill that in below under <strong>Address</strong>.",
    'help.settings.address' => "Only fill in what you want to use on your website or in business documents. For an ordinary website none of these details are required.",
    'help.settings.company_city' => "The town or city of your address. If you fill it in, it also appears at the bottom of the emails the website sends.",
    'help.settings.country' => "The country of your address, as a two-letter code: <strong>NL</strong> for the Netherlands, <strong>BE</strong> for Belgium. If you leave it empty, NL is used.",
    'help.settings.primary_language' => "Your website exists in Dutch and in English. Here you choose which of the two a visitor sees first.\n\nWhere a translation is missing, the website shows the text in this language instead. The CMS itself does not change language here: you set that under <strong>My account</strong>.",
    'help.settings.seo_description' => "A <strong>meta description</strong> is a short summary of a page. Search engines such as Google often show it under the title in their results; you do not see it on the website itself.\n\nEvery page can have its own. This default is only used on pages that have none. If you have nothing general to say, leave it empty: the same sentence everywhere helps nobody.",
    'help.settings.robots' => "Search engines such as Google visit websites to include their pages in search results. That is called <strong>indexing</strong>.\n\nWhen this switch is on, they may. Only switch it off while your website is unfinished and must not be found yet, and switch it back on as soon as the website goes live. Off asks search engines to leave out every page.",
    'help.pages.overview' => "This is where you manage the pages of your website. Click a page to change its content or settings.",
    'help.page.seo' => "These details decide how search engines such as Google can understand this page, and often how it is shown in their results. You do not see them on the page itself.\n\nEverything here is optional. Leave a field empty and the website uses a default.",
    'help.page.seo_title' => "The title of the page in search results and in the browser tab. Say clearly what the page is about, with the main subject first.\n\nWrite for people: repeating the same keywords does not help. Leave the field empty and the title automatically becomes <strong>Page title — :site</strong>.",
    'help.page.meta_description' => "A short summary of the page, in one or two sentences, that tells someone in the search results what the page is about. The technical name for it is <em>meta description</em>.\n\nSearch engines often show it under the title, but they may also pick another piece of the page text themselves. Leave the field empty and the website uses the default description from Settings, if one is filled in.",
    'help.page.url' => "The web address is the last part of this page's URL. In <strong>mysite.com/contact</strong>, <strong>contact</strong> is the web address. The technical name for it is <em>slug</em>.\n\nThe menu, the footer and the header button point at the page itself rather than at this address, so those links follow a change automatically.",
    'help.page.url_new' => "The web address is the last part of this page's URL. In <strong>mysite.com/contact</strong>, <strong>contact</strong> is the web address. The technical name for it is <em>slug</em>.\n\nAs long as you do not change this field yourself, the CMS makes the address from the title. If that address is already taken, a number is added. You can change it freely until the page exists; after that it is protected against accidental changes.",
    'help.page.show_breadcrumb' => "The breadcrumb trail is the small line at the top of the page showing a visitor where they are, for example <strong>Home / Contact</strong>.

The name in it is this page's title, so renaming the page changes the trail with it. Switch this off and the line disappears from this page; the rest of the page stays as it is.",
    'help.page_hero.eyebrow' => "A short word or phrase in small capitals above the title, for example the subject of the page.\n\nLeave it empty and nothing appears above the title.",
    'help.page_hero.title' => "The large heading at the top of the page, and its most important title: search engines and screen readers read it first.",
    'help.page_hero.lead' => "One or two sentences under the title that say what the page is about.\n\nLeave it empty and no text appears under the title.",
    'help.page_hero.content_position' => "Where the title and the text sit in the heading: left, centre or right. Left is how a page heading always looked.\n\nA background photo keeps filling the full width; only the text moves. Beside a photo the text moves within its own column.",
    'help.page_hero.title_size' => "<strong>Normal</strong> suits most pages. Choose <strong>Small</strong> for a long title and <strong>Large</strong> for a short one.\n\nOn a phone a title never gets larger than normal, so long words keep fitting.",
    'help.page_hero.text_size' => "How large the introduction under the title is. <strong>Normal</strong> suits most pages.",
    'help.page_hero.is_active' => "Switched off, the page heading disappears from the page. Nothing is lost: switch it back on and everything is there again.",
    'help.page_hero.image_mode' => "Where the image goes.\n\nWith <strong>Background</strong> the photo fills the whole heading, with a veil over it so the text stays readable, and the breadcrumb sits over the photo. With <strong>Left of the text</strong> or <strong>Right of the text</strong> the photo has a fixed landscape shape beside the text; on a phone it is then always above the text.\n\nChoose <strong>No image</strong> and a chosen image is detached from the heading when you save. It simply stays in the media library.",
    'help.page_hero.hero_height' => "How tall a heading with a background photo is at least. <strong>Medium</strong> is the height a page heading with a photo always had. A long title or introduction makes the heading taller by itself.\n\nOn a phone all three are lower, so some of the page stays in view under the heading.",
    'help.page_hero.image_alt' => "What a screen reader says about the photo beside the text. If the text from the media library is shown here, this heading follows that text; change it and your text applies here only.\n\nA background photo is not read out: it sets the mood, and the words of the heading already say what the page is about.",
    'help.portfolio.overview' => 'This is where you manage your portfolio: its items and their categories. Where the items appear on the website is decided by a gallery block on a page.',
    'help.portfolio.new_item' => 'An image is enough. Alt text, title, short text and category may stay empty; fill them in later whenever you like. Once the item exists you can also give it a project page of its own, with text and extra images.',
    'help.portfolio.image' => 'The image is the portfolio item. Choose it from the media library, or upload a new file there. It is only linked to this item when you create the item.',
    'help.portfolio.replace_image' => 'Choose another image from the media library, or upload a new one there. The current one stays until you click Save.',
    'help.portfolio.alt' => 'A screen reader reads this text out to people who cannot see the image. Describe the image when it carries information. If the image is only decorative, this field may stay empty.',
    'help.portfolio.title' => 'The name of the work. Visitors see it on the image in the gallery. May stay empty.',
    'help.portfolio.subtitle' => 'A short line under the title, for example the material or the client. Shown on the image in the gallery and at the top of the project page. May stay empty.',
    'help.portfolio.categories' => 'Categories let visitors filter the gallery. Tick one or more, or none: an item without a category simply stays visible under "All".',
    'help.portfolio.visible' => 'Off: the item is kept, but it appears in no gallery on the website.',
    'help.forms.overview' => "You create a form here once and then place it on as many pages as you like with the <strong>Form</strong> block. When a form is switched off, it is shown on no page at all and the website accepts no submissions for it.",
    'help.forms.active' => "On: the form appears on every page where you placed it with a block, and visitors can send it.\n\nOff: the form disappears from those pages and the website no longer accepts submissions for it, not even from someone who still had the page open. The fields, the settings and the stored submissions simply stay. Switch it back on and it works as before straight away.",
    'help.forms.name' => "Only for you: this name is how you recognise the form in the overview and when you choose it in a block. Visitors never see it.",
    'help.forms.thank_you_message' => "The text a visitor sees in place of the form once it has been sent. If you leave it empty, it says <strong>Thanks — your message has been sent.</strong>",
    'help.forms.notification_email' => "Every time someone sends this form, this address receives an email with the answers. If you leave it empty, that email goes to the email address from Settings.",
    'help.forms.store_submissions' => "On: every submission is also stored in the CMS. You can read them back under <strong>Submissions</strong>, and a submission is not lost if sending the notification email fails.\n\nOff: the email is the only place a submission arrives. What the visitor filled in is not stored in the database, and if sending the email fails, the visitor sees an error instead of a thank-you.\n\nStored submissions are personal data. Only people with the <strong>View form submissions</strong> permission can read them. They stay until you delete them yourself, even if you switch this setting off later.",
    'help.forms.field_label' => "What the visitor reads with the field, such as <strong>Your name</strong> or <strong>What is your question about?</strong>

From the first label the CMS also makes the fixed name answers are stored under. You can change the label itself later.",
    'help.forms.field_help' => "A short explanation under the label, such as <strong>We only call if you ask us to</strong>. Leave it empty when the label says enough.",
    'help.forms.field_placeholder' => "Light grey text in the field while the visitor has not typed anything yet, such as <strong>name@example.com</strong>. It disappears as soon as the visitor types and is never sent. In technical terms this is a <em>placeholder</em>.",
    'help.forms.field_required' => "On: the form is only sent once the visitor has filled in this field. For a checkbox that means: ticked.\n\nOff: the visitor may leave it empty.",
    'help.forms.reply_to' => "Choose an email field of this form. When you click <strong>Reply</strong> on the notification in your email program, your answer goes straight to the address the visitor filled in.\n\nIf you choose nothing, a reply goes to the website's own address. The sender of the notification is always the website; a visitor cannot change it. In technical terms this is the <em>Reply-To</em> address.",

