    'shop_settings.email_signature' => 'Sign-off',
    'shop_settings.restore_defaults' => 'Restore standard text',
    'shop_settings.restore_defaults_confirm' => 'Put the standard text into every field of this email? Your own text stays saved until you click Save.',
    'shop_settings.restore_defaults_done' => 'The standard text is in the fields. Click Save to use it, or leave the page to keep your own text.',
    'shop_settings.warning_no_sender' => 'Confirmation emails cannot be sent right now: there is no email address to send them from. Fill in an email address under <a href="/admin/settings.php">Settings</a>.',
    'shop_settings.warning_no_notification_address' => 'Confirmation emails are not being sent right now: no address is set up for the shop’s notification of each new order. That address lives in the server configuration (SHOP_NOTIFICATION_EMAIL), not in the CMS. Ask whoever hosts or builds your website to set it.',
    'help.shop_settings.intro' => "This is where you set what only your webshop needs: the details on invoices, the order number and the email a customer receives after an order.\n\nNothing on this page is required. Whatever you leave empty gets a standard value or stays off the invoice.",
    'help.shop_settings.company' => "These details go on every new invoice. An invoice that has already been made never changes along with them.",
    'help.shop_settings.company_name' => "Your business's official name as it belongs on an invoice, for example the name you are registered under if it differs from your website's name.\n\nIf you leave it empty, the <strong>website name</strong> goes on the invoice.",
    'help.shop_settings.vat_id' => "Your VAT identification number, if you have one, for example NL123456789B01.\n\nIf you do not charge VAT, for instance because you use the small-business scheme, leave it empty.",
    'help.shop_settings.website' => "The web address shown on the invoice, for example www.yourshop.com. Leave it empty if you do not want one.",
    'help.shop_settings.invoices' => "The webshop makes an invoice itself as soon as an order is paid. Here you choose how the invoice number begins and a few fixed texts on the invoice.",
    'help.shop_settings.invoice_prefix' => "The letters before every invoice number. With <strong>INV</strong> an invoice number looks like INV2026-000001: the webshop adds the year and the sequence number itself. Want a dash between the letters and the year? Type <strong>INV-</strong>.\n\nUse letters, digits, - and _ (at most 20 characters, starting with a letter or digit); a / or : is not possible, because the invoice number is also the name of the PDF file. If you leave it empty, INV is used. A change only applies to new invoices.",
    'help.shop_settings.invoice_tax_note' => "A fixed sentence about VAT or other rules that must be on every invoice, for example that you use the small-business scheme (KOR).\n\nOnly fill this in if you are sure what belongs there. If you leave it empty, nothing is shown.",
    'help.shop_settings.invoice_payment_note' => "A short sentence about the payment, for example <em>Paid with iDEAL.</em> If you leave it empty, nothing is shown.",
    'help.shop_settings.invoice_footer_text' => "Small text at the very bottom of the invoice, a thank-you for example. If you leave it empty, nothing is shown.",
    'help.shop_settings.order_prefix' => "The letters or digits before every order number. With <strong>ORD</strong> an order number looks like ORD-2026-000127. Your customer sees it in the email, when paying and on the invoice.\n\nLetters and digits only, 10 characters at most. If you leave it empty, ORD is used. An order keeps the number it was given: a change only applies to new orders.",
    'help.shop_settings.email' => "A customer receives this email as soon as their payment has gone through. You write the text around it. The webshop adds the product list, the prices, the addresses and the invoice itself, so those are always right.",
    'help.shop_settings.placeholders' => "Placeholders are words between double curly braces. In every email the webshop replaces them with the details of that order, and you can use them in every field of this email.\n\nType them exactly, braces included. A word between braces that is not listed below simply stays in the email as text.",
    'help.shop_settings.placeholder.customer_name' => "The customer's name as entered at checkout: first name and last name.",
    'help.shop_settings.placeholder.order_number' => "The order number, for example ORD-2026-000127.",
    'help.shop_settings.placeholder.order_date' => "The date of the order, for example 14-03-2026.",
    'help.shop_settings.placeholder.order_total' => "The order total including shipping, for example € 54,90.",
    'help.shop_settings.placeholder.site_name' => "The name the webshop sends email under. Usually that is your website's name from Settings.",
    'help.shop_settings.email_subject' => "The subject line the customer sees in their inbox.\n\nIf you leave it empty, the webshop uses the standard text.",
    'help.shop_settings.email_heading' => "The large heading at the top of the email.\n\nIf you leave it empty, the webshop uses the standard text.",
    'help.shop_settings.email_intro' => "The text at the top of the email, above the order summary. A new line in the field is a new line in the email.\n\nIf you leave it empty, the webshop uses the standard text.",
    'help.shop_settings.email_before_items' => "An extra sentence directly above the product list. If you leave it empty, nothing is shown.",
    'help.shop_settings.email_after_items' => "An extra sentence directly below the product list, about delivery times for example. If you leave it empty, nothing is shown.",
    'help.shop_settings.email_closing' => "The closing sentence at the bottom of the email.\n\nIf you leave it empty, the webshop uses the standard text.",
    'help.shop_settings.email_signature' => "Your name or a greeting below the closing text, for example <em>Best, Sanne</em>. If you leave it empty, nothing is shown.",
    'help.shop_settings.restore_defaults' => "Puts the text the webshop started with back into every field of this email. You see that text in the fields first; only when you click <strong>Save</strong> does it replace your own.",
