    'settings.uit_betekent_elke_publieke' => 'Off means <em>every</em> public page gets <code>noindex</code>. Only switch it off for a site that must not be found yet &mdash; turn it back on as soon as the site is live.',
    'settings.zoekmachines_mogen_website_indexeren' => 'Search engines may index this website',
    'settings.gebruikt_pagina_s_zelf' => 'Used on pages that have no meta description of their own. Leave it empty to show none at all &mdash; that beats the same sentence everywhere. Guideline: 120 to 160 characters.',
    'settings.standaard_meta_description' => 'Default meta description',
    'settings.standaarden_waar_elke_pagina' => 'The defaults every page falls back on. The title suffix is the <strong>website name</strong> and the default share image is the <strong>default share image</strong>, both on the General tab &mdash; each exists once, so the two cannot drift apart.',
