    'setup.homepage_bestaat_al_wil' => 'The homepage already exists. Would you like a few commonly used pages alongside it? Each page gets the blocks such a page usually has, lands in your page overview as a <strong>draft</strong>, and gets a menu item that only becomes visible once you publish it. Feel free to pick none — making them later is just as easy.',
    'setup.5_startpagina_s' => '5. Starting pages',
    'setup.site_kern_cms_zet' => 'At heart this site is a CMS. Only switch on what you use — switching something off removes nothing and can be undone later. What is off contributes nothing: no menu items, no permissions, no public addresses and no extra files for the visitor.',
