    'setup.vijf_kleuren_n_lettertypecombinatie' => 'Five colours, one typeface pairing and the shape of the buttons. Borders, shadows and hover tints are derived from them, so they always go together. Changing this later under Design is just as easy.',
    'setup.3_vormgeving' => '3. Design',
    'setup.kies_upload_logo_pictogrammen' => 'Choose or upload your logo and icons. Everything here is optional: without a logo the site simply shows the name as text, and without a share image it is simply left out. Whatever you upload here lands in the media library.',
