    'block_detail.focuspunt' => 'Focus point',
    'help.block_detail.focuspunt' => 'A gallery picture sits in a square frame. Choose which part of the photo shows in it: click one of the nine points, drag the photo or use the sliders, and zoom in when only part of the photo should fill the square. Point and zoom belong to this gallery; the photo in the media library, or the product\'s, project\'s or post\'s own, does not change. When that product later gets another photo, point and zoom stay. A phone uses the same point and zoom.',
