    'media.responsive.legend' => 'Picture display',
    'help.media.responsive' => 'How the picture sits in its frame. A frame crops a photo when the shape does not fit; the focus point decides which part stays in view. Dragging or choosing a point decides which part of the photo is central. Zoom decides how far in you go: 100% fills the frame exactly, 200% is twice as close. Reset picture puts the point back in the middle and the zoom at 100%. The photo itself never changes. Under "On a phone" you can choose a picture of its own, a focus point with its own zoom or another display for a phone.',
    'media.responsive.focus' => 'Focus point',
    'media.responsive.focus_hint' => 'Drag the picture in the frame, or choose one of the nine points. Zoom brings the photo closer.',
    'media.responsive.axis_x' => 'Horizontal',
    'media.responsive.axis_y' => 'Vertical',
    'media.responsive.value' => 'Horizontal :x%, vertical :y%',
    'media.responsive.contain_note' => 'With "Whole picture" the whole photo is visible. The focus point then only decides where it sits in the frame, and zoom is not available.',
    'media.responsive.fit' => 'Display in the frame',
    'help.media.responsive.fit' => 'Fill covers the whole frame and crops the rest of the photo; the focus point decides what stays visible. Whole picture shows the whole photo; where it does not fill the frame, the block\'s background shows.',
