    // Header & navigatie (admin/navigation.php, admin/navigation-item.php): Navigation phase A.
    'help.navigation.overview' => "The <strong>menu</strong> and the <strong>buttons</strong> sit at the top of every page of your website. On a phone both appear as soon as a visitor taps the menu icon.\n\nSet the order with the arrows. An item you hide is kept. When a link points at a draft page or at a part of the site that is switched off, it disappears from the website for the time being and comes back by itself.",
    'help.navigation.visible' => 'When this is off, the item disappears from the website but stays here. That way you take something away for a while without having to make it again.',
    'help.navigation.text' => 'The words visitors see in the header. Keep it short: a long text takes up a lot of room, especially on a button. When you leave the translation empty, the website uses the text in the main language.',
    'help.navigation.label_follows' => "When this is on, the menu shows the title of the chosen page, in every language of your website. When you change that page's title later, the menu follows by itself.\n\nTurn it off to write your own text, per language.",
    'help.navigation.destination' => 'Choose <strong>a page of this website</strong> for a page you manage yourself: the link follows along when you change that page\'s address later. <strong>A fixed part of the website</strong> is a part that is not an ordinary page, such as the cart. <strong>Another address</strong> is for another website.',
    'help.navigation.route' => 'Parts of the website that are not ordinary pages, such as the homepage, the shop and the cart. A part that is switched off cannot be chosen here.',
    'help.navigation.external' => 'A full address starting with https://, or an address on this website starting with a slash, such as /contact.',
    'help.navigation.new_tab' => 'Useful for another website: your own website stays open. For a page of your own website it is usually not needed.',
    'help.navigation.presentation' => 'A <strong>link</strong> sits in the menu. A <strong>button</strong> sits on the right of the header and stands out more: use it for the one or two things visitors should mainly do, such as getting in touch.',
    'help.navigation.variant' => 'Prominent is a filled button in your website\'s main colour. Subtle has just an outline. With two buttons, make one prominent and one subtle.',
