    'shop.overview.heading' => 'Product overview',
    'shop.overview.intro' => 'The Shop does not create a page listing every product on its own. Choose here which page is your product overview, or that there is none. Only a page with a Product grid block can be the overview: first add a Product grid to the page you want (Pages → the page → Add block), where the products should appear. Product pages, the cart and the breadcrumb then link to that page.',
    'shop.overview.label' => 'Product overview',
    'shop.overview.help' => 'Product pages, the cart and the breadcrumb link to this page. The old address /shop.php sends visitors there. With No overview page nothing links to an overview and /shop.php answers \'not found\'.',
    'shop.overview.none' => 'No overview page',
    'shop.overview.builtin' => 'Automatic overview at /shop.php (old behaviour)',
    'shop.overview.page_option' => 'Existing page: :title',
    'shop.overview.page_option_draft' => 'Existing page: :title (draft)',
    'shop.overview.builtin_note' => 'This site still shows the automatic overview from before this setting. Choose a page of your own to decide what is on it; the automatic overview cannot be chosen again afterwards.',
    'shop.overview.draft_note' => 'The chosen page is still a draft. As long as it is not published, nothing links to it.',
    'shop.overview.no_grid_note' => 'This page has no visible Product grid (yet), so it lists no products. Add the block in the page editor, or choose another page.',
    'shop.overview.edit_page' => 'Edit page',
    'validation.shop_overview_invalid' => 'Choose a page with a Product grid block, or No overview page.',
    'shop.overview.has_grid' => '✓ Product grid',
    'shop.overview.no_grid' => 'no Product grid',
    'nav.payments' => 'Payments',
    'payments.title' => 'Payments',
    'payments.title_admin' => 'Payments — Admin',
    'help.payments.intro' => "This is where you connect your webshop to Mollie, the company that processes your customers' payments (iDEAL, credit card and more).\n\nYou start in test mode: you can try everything without any real money changing hands. Only when that works do you take the shop live.",
    'payments.status.title' => 'Status',
    'payments.status.badge.not_configured' => 'Not set up',
    'payments.status.badge.test' => 'Test mode',
    'payments.status.badge.live' => 'Live',
    'payments.status.badge.problem' => 'Problem',
    'payments.status.lead.not_configured' => 'Your webshop cannot take payments yet. Follow the steps below to connect Mollie; it usually takes about fifteen minutes.',
    'payments.status.lead.test' => 'Your webshop is connected in test mode. Checkout works, but no real money is transferred. Use this to try everything out.',
    'payments.status.lead.live' => 'Your webshop takes real payments. The money arrives in your Mollie account.',
    'payments.status.lead.problem' => 'A key is set, but the connection to Mollie does not work. Customers cannot pay right now. What is wrong is shown below.',
    'payments.status.lead.problem_url' => 'The live key works, but Mollie cannot handle real payments with the address of this site. Customers cannot pay right now. What is wrong is shown below.',
    'payments.status.provider' => 'Payment provider',
    'payments.status.mode' => 'Mode',
    'payments.status.mode_test' => 'Test mode (no real money)',
    'payments.status.mode_live' => 'Live (real payments)',
    'payments.status.mode_unknown' => 'Unknown',
    'payments.status.key' => 'Key',
    'payments.status.key_environment' => ':key — set in the server environment',
    'payments.status.key_cms' => ':key — stored in the CMS',
    'payments.status.key_none' => 'No key for this mode yet',
    'payments.status.connection' => 'Connection',
    'payments.status.connection_none' => 'Not tested yet: there is no key',
    'payments.status.setup_cta' => 'Set up Mollie',
    'payments.test_connection' => 'Test connection',
    'payments.testing' => 'Testing…',
    'payments.test_failed_request' => 'The test could not run. Are you still signed in? Please try again.',
    'payments.result.ok_test' => 'Connection successful. This test key works. Payment methods Mollie offers for your account: :count.',
    'payments.result.ok_live' => 'Connection successful. This live key works. Payment methods Mollie offers for your account: :count.',
    'payments.result.no_key' => 'There is no key to test yet. Paste your API key into the field first.',
    'payments.result.key_format' => 'This is not a Mollie API key. A key starts with test_ or live_ and is about 35 characters long, without spaces. Copy it again from your Mollie dashboard.',
    'payments.result.unreadable' => 'The stored key can no longer be read, for example because the site moved to another server. Paste the key again and save.',
    'payments.result.refused' => 'Mollie refuses this key. Check that you copied the whole key and that it still exists in your Mollie dashboard.',
    'payments.result.unreachable' => 'Mollie cannot be reached right now. That is usually not on your side; try again in a few minutes.',
    'payments.result.unexpected' => 'Mollie gave an unexpected answer. Try again later. If it keeps happening, ask your web developer to look at the server log.',
    'payments.setup.title' => 'Connecting Mollie, step by step',
    'payments.setup.intro' => 'Never set up a payment provider before? No problem. Work through these six steps from top to bottom; you can always continue later.',
    'payments.setup.done' => 'Done',
    'payments.setup.current' => 'Now',
    'payments.step1.title' => 'Step 1 — Create a Mollie account',
    'payments.step1.body' => "Mollie processes the payments for your webshop. Create an account on mollie.com and fill in your company details. Mollie also asks you to add your website (a <em>website profile</em>); enter the address of this webshop there.\n\nYou can test right away. Receiving real payments has to wait until Mollie has checked your details, which usually takes a few working days.",
    'payments.step1.link' => 'Go to mollie.com (opens in a new tab)',
    'payments.step2.title' => 'Step 2 — Find your Test API key',
    'payments.step2.body' => "Log in to your Mollie dashboard and go to <strong>Developers → API keys</strong>. There are two keys there:\n\n<strong>Test API key</strong>: starts with test_. Use it for practice payments. No real money ever moves.\n<strong>Live API key</strong>: starts with live_. With it your customers really pay. You only need it in step 6.\n\nCopy the test key. Treat a key like a password: share it with nobody and do not put it in an email.",
    'payments.step2.link' => 'Go to your Mollie dashboard (opens in a new tab)',
    'payments.step3.title' => 'Step 3 — Paste the key here',
    'payments.step3.body' => 'Paste the test key into the <strong>Test API key</strong> field below and click Save. Mygdala stores the key encrypted. After that you only see its start and its last four characters, for example test_••••••••abcd. The whole key is never shown again.',
    'payments.step3.link' => 'Go to the API keys',
    'payments.step4.title' => 'Step 4 — Test the connection',
    'payments.step4.body' => "Click <strong>Test this key</strong> next to the key, or <strong>Test connection</strong> at the top. Mygdala then asks Mollie which payment methods are switched on for your account. Nothing is paid, no order is created and nothing changes.\n\nIf it says Connection successful, your key works.",
    'payments.step5.title' => 'Step 5 — Make a test payment',
    'payments.step5.body' => 'Order something in your own webshop, exactly the way a customer does. Because you are in test mode, Mollie then lets you choose how the payment ends: paid, failed, cancelled or expired.',
    'payments.step5.link' => 'How to make a test payment',
    'payments.step6.title' => 'Step 6 — Go live',
    'payments.step6.body' => "Has Mollie approved your account? Then copy your <strong>Live API key</strong> from the dashboard, paste it into the Live API key field and choose Live under <strong>Test or live</strong>. Click Save.\n\nMygdala tests the live key first. Only when it works does your webshop start taking real payments. You can always go back to test mode.",
    'payments.step6.link' => 'Go to Test or live',
    'payments.keys.title' => 'API keys',
    'help.payments.keys' => "An API key is a kind of password your webshop uses to talk to Mollie. You find both keys in your Mollie dashboard under <strong>Developers → API keys</strong>.\n\nMygdala stores a key encrypted and afterwards only shows its start and its last four characters.",
    'payments.keys.test_label' => 'Test API key',
    'payments.keys.live_label' => 'Live API key',
    'help.payments.test_key' => 'Starts with test_. Use it for practice payments without real money. This is where you begin.',
    'help.payments.live_key' => 'Starts with live_. With it your customers really pay. Storing a live key does not take your webshop live yet: you choose that yourself under Test or live.',
    'payments.keys.stored' => 'Stored: :hint (since :date)',
    'payments.keys.none' => 'No key stored yet.',
    'payments.keys.unreadable' => 'A key is stored (:hint), but it can no longer be read. Paste it again and save.',
    'payments.keys.keep_hint' => 'Leave this field empty to keep the stored key. A new key replaces the old one as soon as you save.',
    'payments.keys.test_this' => 'Test this key',
    'payments.keys.placeholder_test' => 'test_…',
    'payments.keys.placeholder_live' => 'live_…',
    'payments.keys.environment_title' => 'Configured through the server environment',
    'payments.keys.environment_body' => 'The Mollie key of this webshop is set in the server environment (MOLLIE_API_KEY in the .env file): :key. You cannot change or erase it here, and the mode follows the key: a key starting with test_ means test mode, live_ means live. Want to manage the keys here? Ask your web developer to remove MOLLIE_API_KEY from the server environment.',
    'payments.keys.environment_invalid' => 'not a valid Mollie key',
    'payments.keys.confirm_live' => 'Yes, replace the live key',
    'help.payments.confirm_live' => 'Your webshop is live and has already received payments. After saving, new payments go through the new key. Make sure it belongs to the same Mollie account; otherwise Mygdala can no longer update payments that are still open.',
    'payments.mode.title' => 'Test or live',
    'payments.mode.legend' => 'Mode',
    'help.payments.mode' => 'In test mode you and your customers make practice payments without real money. Live means real payments. Live can only be switched on when there is a live key and it works; Mygdala checks that when you save.',
    'payments.mode.test' => 'Test mode',
    'payments.mode.live' => 'Live',
    'payments.mode.explain' => 'Mygdala never takes your webshop live by itself, not even when a live key is stored. You always choose that yourself, here.',
    'payments.mode.environment' => 'The mode follows the key in the server environment: :mode.',
    'payments.testpay.title' => 'Making a test payment',
    'payments.testpay.intro' => 'This is how you try a whole order with your webshop\'s real checkout, without real money. Only do this in test mode.',
    'payments.testpay.step1' => 'Check at the top that the status is Test mode.',
    'payments.testpay.step2' => 'Open your webshop with the button below. It opens in a new tab.',
    'payments.testpay.step3' => 'Put a product in the cart.',
    'payments.testpay.step4' => 'Go to checkout and fill in your details, the way a customer does.',
    'payments.testpay.step5' => 'Choose a payment method and place the order. You now arrive at Mollie.',
    'payments.testpay.step6' => 'In test mode Mollie shows a test page. Choose there how the payment ends: paid, failed, cancelled or expired. That way you can practise every outcome.',
    'payments.testpay.step7' => 'Mollie sends you back to your webshop, where you see how the order stands.',
    'payments.testpay.step8' => 'Look in the CMS under Shop → Orders: the order is there, labelled TEST, with the payment status you chose. For a paid test order the confirmation email has been sent, marked as a test and without an invoice.',
    'payments.testpay.open_shop' => 'Go to the webshop (opens in a new tab)',
    'payments.testpay.not_test' => 'The button to the webshop appears as soon as the status is Test mode. In Live an order is really paid.',
    'payments.webhook.title' => 'Webhook',
    'payments.webhook.intro' => 'Mollie tells your webshop through a webhook when a payment changes, for example from open to paid. Mygdala gives Mollie this address itself with every payment. So there is nothing to set up in Mollie.',
    'payments.webhook.url_label' => 'Webhook address',
    'payments.webhook.copy' => 'Copy',
    'payments.webhook.copied' => 'Copied',
    'payments.webhook.unreachable' => 'The address of this site (:base) cannot be reached from the internet, for example because the site runs on your own computer. Mollie cannot call such an address, so Mygdala sends no webhook then. In test mode that is fine: a test order is updated once the customer comes back to the order page. Live is only possible with a public https address.',
    'payments.webhook.base_missing' => 'The address of this site has not been set yet. Set it in the setup wizard, or ask your web developer to set APP_URL: otherwise Mollie does not know where to reach your webshop.',
    'payments.webhook.not_https' => 'Your site does not use https. For real payments a secure connection (https) is strongly recommended.',
    'payments.error.pinned_by_environment' => 'The Mollie key is set in the server environment. You cannot change or erase it here.',
    'payments.error.key_format' => 'This is not a Mollie API key. A key starts with test_ or live_ and is about 35 characters long, without spaces.',
    'payments.error.live_key_in_test_field' => 'This is a live key (it starts with live_). Paste it into the Live API key field.',
    'payments.error.test_key_in_live_field' => 'This is a test key (it starts with test_). Paste it into the Test API key field.',
    'payments.error.mode_invalid' => 'Choose Test mode or Live.',
    'payments.error.live_needs_key' => 'Live can only be switched on when there is a live key. Paste your Live API key first.',
    'payments.error.live_key_unreadable' => 'The stored live key can no longer be read. Paste it again.',
    'payments.error.live_check_failed' => 'Not saved: the live key does not work yet. :reason',
    'payments.error.confirm_live_key' => 'Your webshop is live and has already received payments. Switch on the confirmation if you really want to replace the live key.',
    'payments.error.storage_key_not_created' => 'The key could not be stored safely: Mygdala could not create a key file in the protected storage outside the website. Ask your hosting provider or web developer to make that folder writable, or to set APP_KEY in the server environment. Nothing was changed.',
    'payments.error.storage_key_invalid' => 'The key could not be stored safely: APP_KEY in the server environment, or the key file, is not a valid key. Ask your web developer to look into it. Nothing was changed.',
    'payments.error.storage_no_key' => 'The key could not be stored safely. Nothing was changed.',
    'payments.error.storage_unreadable' => 'The key could not be stored safely. Nothing was changed.',
    'payments.save_failed' => 'Saving failed. Nothing was changed. Please try again.',
    'payments.methods.title' => 'Payment methods',
    'help.payments.methods' => "Mollie decides which payment methods you <em>can</em> offer: the methods switched on in your Mollie dashboard. Here you choose which of them your customers really see at checkout.\n\nIs a method missing here? Switch it on in your Mollie dashboard first and come back. Test mode and Live can differ: in test mode Mollie can show methods that are not yet approved for live.",
    'payments.methods.intro' => 'Tick the payment methods your customers see at checkout. The list comes straight from Mollie: you can only offer what is switched on for your account.',
    'payments.methods.legend' => 'Offered at checkout',
    'payments.methods.available' => 'Available at Mollie',
    'payments.methods.unavailable' => 'Not available at Mollie',
    'payments.methods.default_note' => 'You have not chosen anything here yet. Your webshop therefore offers iDEAL and credit card, as always. Another method is only switched on once you tick it and save.',
    'payments.methods.unknown_note' => 'The connection to Mollie does not work right now, so Mygdala does not know which methods are available. You can switch methods off; switching new ones on is possible once the connection works.',
    'payments.methods.mode_note' => 'This list belongs to :mode. Test mode and Live can have different methods.',
    'payments.methods.unavailable_note' => 'A ticked method that Mollie does not (or no longer) offer cannot be used by a customer: checkout then fails. Switch it off, or switch it on in your Mollie dashboard.',
    'payments.error.methods_none' => 'Choose at least one payment method. Without one nobody can check out.',
    'payments.error.methods_invalid' => 'An unknown payment method was sent. Reload the page and try again.',
    'payments.error.methods_unverifiable' => 'Mollie cannot be reached right now, so new payment methods cannot be checked. You can switch methods off; switching them on is possible once the connection works.',
    'payments.error.method_unavailable' => 'The payment method :method is not switched on in your Mollie account. Switch it on in your Mollie dashboard first.',
    'validation.factuurprefix_ongeldig' => 'The invoice number prefix may only contain letters, digits, - and _, must start with a letter or digit and is at most 20 characters long.',
    'shop_settings.invoice_prefix_legacy' => 'The current prefix ":prefix" contains characters an invoice number must not have, such as / or :. New invoices therefore use ":used". Existing invoices stay exactly as they are. Choose a prefix with only letters, digits, - and _ to resolve this.',
    'payments.testpay.note' => 'Good to know: a test order appears under Shop → Orders labelled TEST. It does not count towards the revenue on the dashboard and never gets an invoice, so your real invoice numbers stay consecutive. It does get an order number and a confirmation email, marked as a test. A test order stays a test order after you switch to Live.',
    'perm.payments.manage.label' => 'Manage payments',
    'perm.payments.manage.description' => 'The Mollie keys, test or live, and the payment methods. Decides which Mollie account customers pay into; only a Super Admin can grant this.',
    'shop.test_badge' => 'TEST',
    'shop.test_order_notice' => 'Test order: paid with a Mollie test key, so without real money. It does not count towards revenue and gets no real invoice.',
    'shop.test_order_invoice' => 'Test order — no real invoice is issued.',
    'payments.status.live_url_problem' => 'The website URL must be set correctly before Live can be used. :reason Customers cannot pay right now. Set the address in the setup wizard, or ask your web developer to set APP_URL.',
    'payments.error.live_needs_url' => 'Live can only be switched on once the site address is right. :reason',
    'payments.url.missing' => 'The site address has not been set yet.',
    'payments.url.not_https' => 'The site address does not start with https://; real payments only go over a secure connection.',
    'payments.url.not_public' => 'The site address is a local or private address Mollie cannot reach.',
    'shop.stock.heading' => 'Stock',
    'shop.stock.track' => 'Track stock',
    'shop.stock.untracked_note' => 'Off: the product can be ordered without limit, as always. Switch this on to keep a stock count; at 0 the shop shows Out of stock and nobody can order it.',
    'shop.stock.per_variant_note' => 'This product has variants: the stock is kept per variant, under Variants. Each variant can be ordered or be out of stock on its own.',
    'shop.stock.quantity' => 'Stock',
    'help.shop.stock.quantity' => 'How many can be ordered. An order takes them as soon as the customer goes to pay; if the payment fails, expires or is canceled they come back automatically. A whole number of 0 or more.',
    'shop.stock.not_tracked' => 'Stock not tracked',
    'shop.stock.sold_out' => 'Out of stock',
    'shop.stock.in_stock' => ':count in stock',
    'shop.stock.variant_summary' => ':count variants, :sold_out of them out of stock.',
    'validation.stock_invalid' => 'Enter a stock: a whole number of 0 or more.',
    'validation.stock_changed' => 'The stock changed in the meantime, probably because of an order: there are now :current. Check the number and save again.',
    'shop_settings.stock_mail_title' => 'Back in stock',
    'help.shop_settings.stock_mail' => 'When a product or variant with tracked stock is at 0, a visitor can ask for one email as soon as it can be ordered again. That email goes out automatically once the stock is above 0 again, also when a failed payment gives stock back. Here you set the subject and the text, per website language: switch the language at the top. An empty field means the standard text in that language. A button to the product is always added below the text.',
    'help.shop_settings.stock_mail_placeholders' => 'These words between double braces are replaced in every email: {{product_name}} by the product name in the visitor\'s language, {{variant}} by the chosen variant (empty for a product without variants), {{product_url}} by the product\'s address and {{site_name}} by the site\'s name. Other words between braces stay as they are.',
    'shop_settings.stock_mail_subject' => 'Subject',
    'help.shop_settings.stock_mail_subject' => 'The subject line of the email, and its heading. One line.',
    'shop_settings.stock_mail_body' => 'Text',
    'help.shop_settings.stock_mail_body' => 'The text of the email. An empty line starts a new paragraph. No formatting: the email shows exactly what you type.',
    'shop_settings.stock_waiting_title' => 'Waiting notifications',
    'shop_settings.stock_waiting_summary' => ':waiting requests are waiting for a notification; :due of them can be sent now because their product can be ordered again.',
    'shop_settings.stock_waiting_failed' => 'For :failed requests sending failed before. They are tried again the next time that product is saved, or now with the button below.',
    'shop_settings.stock_waiting_unknown' => 'The number of waiting notifications could not be read right now.',
    'shop_settings.stock_waiting_send' => 'Send waiting notifications now',
    'shop_settings.stock_waiting_sent' => ':sent notifications sent, :failed failed.',
    'shop_settings.stock_waiting_error' => 'The notifications could not be sent right now. Please try again later.',
    'validation.stock_mail_too_long' => ':field may be at most :max characters long.',
    'shop.purchase_mode.label' => 'Sales mode',
    'help.shop.purchase_mode' => 'Order directly: price, quantity and cart, as always. On request: the product is shown as usual, with photos, description, variants and specifications, but without a price (not on product cards or in search engines either) and without a cart; a visitor sees a button to get in touch. The price is kept for when you switch back to Order directly.',
    'shop.purchase_mode.direct' => 'Order directly',
