    'help.block_detail.anker' => 'A word the section can be reached by: with "wood" the section\'s address becomes #wood. Lowercase letters, digits and dashes; a # and spaces are adjusted for you. The section then appears automatically in the anchor navigation below the page\'s head, with its navigation label. Two sections on one page cannot share an anchor. Empty = no anchor.',
