    'help.block_detail.beeldpositie' => 'Which side of the text the main image sits on. On a phone it always sits below the text. This is where the image sits in the section, not a focus point: the main image is never cropped and always shows the whole photo.',
    'help.block_detail.kenmerken' => 'Short points beside the text, each with a fixed tick icon.',
