    'fonts.error_name_required' => 'Give the font a name.',
    'fonts.error_name_length' => 'The name may be at most :max characters.',
    'fonts.error_name_taken' => 'There is already a font with this name.',
    'fonts.error_category' => 'Choose a kind of font from the list.',
    'fonts.error_source' => 'Enter a full web address starting with https:// or http://, or leave the field empty.',
    'pagethemes.font_usage' => 'page theme ":name" (:roles)',
    'help.fonts.name' => 'What the font is called in the CMS, for example "Roboto". Only for you: visitors never see the name. You can always change it.',
    'help.fonts.category' => 'A serif font has small feet on its letters (like Georgia), a sans serif font does not (like Arial). While your font loads, or when a file is missing, the website shows a similar standard font of this kind.',
    'help.fonts.source' => 'Where you got the font or where its licence is, for example its page on Google Fonts. Handy to find back later. The CMS does not check the licence.',
    'help.fonts.files' => 'Choose the files of one family. For each file, say which variant it is: Regular, Bold, Italic and so on. The CMS suggests one from the file name.',
    'help.fonts.role_heading' => 'For every heading of the website. "From the font pairing" uses the heading font of the pairing above.',
    'help.fonts.role_body' => 'For all ordinary text of the website. "From the font pairing" uses the text font of the pairing above.',
    'help.fonts.howto_title' => 'How do I add a font of my own?',
    'help.fonts.howto_intro' => 'You need no technical knowledge. This is how it works with a free font from Google Fonts:',
    'help.fonts.howto_step_1' => 'Open <a href="https://fonts.google.com/" target="_blank" rel="noopener noreferrer">Google Fonts</a> in a new tab.',
    'help.fonts.howto_step_2' => 'Find a font you like and open it.',
    'help.fonts.howto_step_3' => 'Check the licence (on Google Fonts usually the Open Font License, which allows use on a website).',
    'help.fonts.howto_step_4' => 'Click <strong>Get font</strong> and then <strong>Download all</strong>. You get a ZIP file.',
    'help.fonts.howto_step_5' => 'Unpack the ZIP file: double-click it, or right-click it and choose <strong>Extract all</strong>.',
    'help.fonts.howto_step_6' => 'Open the <strong>static</strong> folder. It holds a .ttf file per variant, for example <em>Roboto-Regular.ttf</em>, <em>Roboto-Bold.ttf</em> and <em>Roboto-Italic.ttf</em>. Choose only the variants you need; Regular and Bold are usually enough.',
    'help.fonts.howto_step_7' => 'Click <strong>Add font</strong> here, give it a name and choose those files.',
    'help.fonts.howto_step_8' => 'Check the variant of every file: Regular is <em>Regular</em>, Bold is <em>Bold</em>, Italic is <em>Italic</em>.',
    'help.fonts.howto_step_9' => 'Look at the preview: it appears straight away, before anything is saved.',
    'help.fonts.howto_step_10' => 'Click <strong>Save font</strong>. Then choose it under <strong>Colours and style → Typography</strong> for the headings or the body text, or in a page theme.',
    'help.fonts.howto_other_sources' => 'A font from another website or a font you bought works the same way. If you have the choice, take the WOFF2 files (the "webfont" version): they are the smallest. TTF and OTF work too, they are just a little larger.',
    'help.fonts.howto_limits' => 'Allowed: WOFF2, WOFF, TTF and OTF, at most :max MB per file and :total MB for all your own fonts together. A ZIP file cannot be uploaded: unpack it first.',
    'help.fonts.files_title' => 'What do those files mean?',
    'help.fonts.term_regular' => 'Regular',
    'help.fonts.term_regular_text' => 'The ordinary letters for body text. You always need this file.',
    'help.fonts.term_bold' => 'Bold',
    'help.fonts.term_bold_text' => 'Bold text, and often the headings too. Without this file the browser thickens the letters itself, which looks less good. Medium, SemiBold and ExtraBold are weights in between and above.',
    'help.fonts.term_italic' => 'Italic',
    'help.fonts.term_italic_text' => 'Slanted text. Bold Italic is bold and italic at once.',
    'help.fonts.term_variable' => 'Variable / VariableFont',
    'help.fonts.term_variable_text' => 'One file with every weight. Prefer the separate files from the static folder: then you choose exactly the variant for each file.',
    'help.fonts.term_woff2' => 'WOFF2',
    'help.fonts.term_woff2_text' => 'Made for websites: the smallest file, so the fastest page. Recommended if you have the choice. WOFF is the older, slightly larger version.',
    'help.fonts.term_ttf' => 'TTF and OTF',
    'help.fonts.term_ttf_text' => 'The ordinary font files you also install on your computer. They work on the website, but are larger than WOFF2.',
    'help.fonts.term_missing' => 'Not every family has everything',
    'help.fonts.term_missing_text' => 'Some fonts have no italic or only one weight. That is fine: add what there is.',
    'help.fonts.use_title' => 'Choosing and deleting',
    'help.fonts.use_select' => 'A font you add does nothing yet. You choose it under <strong>Colours and style → Typography</strong> for the headings, the body text or both, or in a page theme. The website only loads the fonts that are really used, so a font you keep but do not choose does not make the website slower. The fonts come from your own website, with no request to Google.',
    'help.fonts.use_delete' => 'A font that is in use cannot be deleted: the CMS then says where it is used. Choose another font there first, then you can delete it. A colour palette never changes the font.',
    'help.fonts.icons_title' => 'Font Awesome and other icons',
    'help.fonts.icons_text' => 'Font Awesome looks like a font, but it is a set of icons. Uploading it here does not give you icons on your website: that also needs a list of which character is which icon, and style rules of its own. So do not choose Font Awesome as the font for headings or text: your text would become unreadable.',
    'help.fonts.icons_later' => 'A library of icons of its own may come later, as a separate part of the design and the Media Library.',

    // --- Button Styles 2.0 (Design -> Buttons, admin/button-style.php) -------
    'buttons.tab' => 'Buttons',
    'buttons.title' => 'Button styles',
    'buttons.intro' => 'A button style is a design for buttons: shape, colours, border, shadow, text, an arrow or icon, and what happens when the mouse is on it. You can make as many as you like and choose per button in a content block which style it uses. Change a style, and every button with that style changes at once.',
    'help.buttons.overview' => 'Two styles are a <strong>default</strong>. The <strong>default button</strong> is used by every button that has not chosen a style of its own, including the buttons of the shop, forms and the cookie notice. The <strong>default second button</strong> is the calmer button next to a first one. A button in a content block set to "Default" therefore follows along by itself.',
